.jg .jg__title{font-family:var(--jg-title-font);font-size:var(--jg-title-size);font-weight:var(--jg-title-weight);letter-spacing:var(--jg-title-tracking);line-height:var(--jg-title-leading)}
.jg .jg__body{font-family:var(--jg-body-font);font-size:var(--jg-body-size);font-weight:var(--jg-body-weight);letter-spacing:var(--jg-body-tracking);line-height:var(--jg-body-leading)}
.jg .jg__button-type{font-family:var(--jg-button-font);font-size:var(--jg-button-size);font-weight:var(--jg-button-weight);letter-spacing:var(--jg-button-tracking);line-height:var(--jg-button-leading)}
june-pour.jg{display:block;position:relative;isolation:isolate;container-type:inline-size;max-width:1680px;min-height:var(--jg-height);aspect-ratio:1.92;margin:0 auto;background:#eee4d4;color:var(--jg-ink);overflow:hidden;scroll-margin-top:110px}.jg *{box-sizing:border-box}.jg [hidden]{display:none!important}.jg h2,.jg h3,.jg p{margin:0;color:inherit}.jg a{color:inherit;text-decoration:none}.jg button{appearance:none;cursor:pointer;color:inherit}.jg strong{font-weight:700}.jg :is(a,button,summary):focus-visible{outline:3px solid var(--jg-ink);outline-offset:4px}
.jg__scenes,.jg__foregrounds,.jg__scenes picture,.jg__foreground{position:absolute;inset:0}.jg__scenes{z-index:0}.jg__scenes img,.jg__foreground img{display:block;width:100%;height:100%;object-fit:cover;object-position:var(--jg-focus,50%) center}.jg__foregrounds{z-index:2;pointer-events:none}.jg__header{position:relative;z-index:1;padding:3.2% 3% 0}.jg .jg__heading{font-size:min(var(--jg-heading-size),15.2cqw);white-space:nowrap;margin:12px 0 8px;line-height:var(--jg-heading-leading)}.jg__eyebrow{text-transform:uppercase;letter-spacing:.15em!important;font-size:11px!important}.jg__intro{max-width:38%;margin-top:10px}.jg__footer{position:absolute;z-index:3;bottom:3%;left:3%;right:3%;display:flex;justify-content:space-between;align-items:flex-end;gap:24px}.jg__choices{max-width:42%;padding:10px 0}.jg__tabs{display:flex;gap:4px;margin-top:10px}.jg .jg__tab{border:0;border-bottom:1px solid #10101055;border-radius:0;min-height:44px;padding:10px 14px;background:transparent;white-space:nowrap}.jg .jg__tab[aria-pressed=true]{background:var(--jg-button-bg);color:var(--jg-button-ink);border-color:var(--jg-button-bg)}.jg__products{position:relative;width:27%;min-width:260px;padding:12px;background:transparent}.jg__product{display:flex;flex-direction:column;gap:6px;min-height:144px}.jg .jg__title{font-size:var(--jg-title-size)}.jg .jg__price{margin-bottom:4px}.jg .jg__primary{display:flex;align-items:center;justify-content:space-between;gap:14px;background:var(--jg-button-bg);color:var(--jg-button-ink);border:1px solid var(--jg-button-bg);border-radius:0;min-height:44px;padding:10px 14px}.jg__arrow{font-family:Arial,sans-serif;font-size:19px;line-height:1;background:none;border:0}.jg__all{display:flex;align-items:center;justify-content:flex-end;gap:8px;min-height:44px;text-decoration:underline!important;text-underline-offset:4px}.jg__details{position:relative;margin-bottom:-44px;z-index:1;width:76px}.jg__details summary{cursor:pointer;display:flex;align-items:center;min-height:44px}.jg__details summary:after{content:'+';margin-left:6px}.jg__details[open] summary:after{content:'âˆ’'}.jg__details>div{position:absolute;bottom:100%;right:0;width:260px;padding:16px;background:#fffaf1;border:1px solid #10101044;box-shadow:0 6px 18px #0002}.jg__fallback{position:relative;z-index:4;background:#fffaf1;padding:16px}.jg__fallback a{display:inline-block;padding:10px;text-decoration:underline}
@media(max-width:1100px) and (min-width:901px){.jg__products{width:29%;min-width:240px}.jg__tab{padding-inline:8px!important}.jg .jg__title{font-size:20px}.jg__product{min-height:138px}}
@media(max-width:900px){june-pour.jg{aspect-ratio:auto;min-height:0;padding:0 0 20px;background:#eee4d4}.jg__header{padding:24px 20px 0;min-height:215px;z-index:3;background:linear-gradient(#f7efe3e6,#f7efe3b3 78%,transparent)}.jg .jg__heading{white-space:normal;font-size:var(--jg-heading-mobile);max-width:100%;line-height:var(--jg-heading-leading);margin:10px 0}.jg__intro{max-width:100%;margin-top:8px}.jg .jg__body{font-size:var(--jg-body-mobile)}.jg .jg__button-type{font-size:var(--jg-button-mobile)}.jg .jg__title{font-size:var(--jg-title-mobile)}.jg__scenes{position:relative;height:var(--jg-mobile-height);margin-top:0;order:1}.jg__scenes picture{overflow:hidden}.jg__scenes img{object-fit:cover;object-position:var(--jg-focus,50%) center}.jg__foregrounds{display:none}.jg{display:flex!important;flex-direction:column}.jg__header{order:0}.jg__footer{order:2;position:relative;inset:auto;display:flex;flex-direction:column;align-items:stretch;gap:12px;margin:0 20px;padding:16px 0;background:transparent;z-index:3}.jg__choices{max-width:none;padding:0}.jg__tabs{gap:4px;margin-top:8px}.jg .jg__tab{flex:1;min-width:0;padding:10px 6px;white-space:normal}.jg__products{width:100%;min-width:0;padding:0;background:none;backdrop-filter:none}.jg__product{min-height:180px}.jg__details>div{left:0;right:auto;width:min(260px,75vw)}.jg__eyebrow{font-size:10px!important}}
@media(prefers-reduced-motion:reduce){.jg *{animation:none!important;transition:none!important}}

@media(max-width:900px){.jg__header{background:none}.jg__scenes:after{content:'';position:absolute;inset:0;pointer-events:none;background:linear-gradient(#eee4d4,transparent 12%,transparent 88%,#eee4d4)}}
{% endstylesheet %}
{% javascript %}

if(!customElements.get('june-pour')){
 customElements.define('june-pour',class extends HTMLElement{
  connectedCallback(){
   this.controller?.abort();this.controller=new AbortController();const options={signal:this.controller.signal};
   this.buttons=[...this.querySelectorAll('[data-select]')];
   this.resizeObserver?.disconnect();this.resizeObserver=new ResizeObserver(()=>this.fitTitle());this.resizeObserver.observe(this);document.fonts.ready.then(()=>{if(this.isConnected)this.fitTitle();});
   this.addEventListener('click',e=>{const b=e.target.closest('[data-select]');if(b&&this.contains(b))this.select(Number(b.dataset.select));},options);
   this.addEventListener('keydown',e=>{const b=e.target.closest('[data-select]');if(!b)return;let i=this.buttons.indexOf(b),n;
    if(e.key==='ArrowRight')n=(i+1)%this.buttons.length;if(e.key==='ArrowLeft')n=(i-1+this.buttons.length)%this.buttons.length;if(e.key==='Home')n=0;if(e.key==='End')n=this.buttons.length-1;
    if(n===undefined)return;e.preventDefault();this.select(n);this.buttons[n].focus();
   },options);
   this.addEventListener('shopify:block:select',e=>{const b=this.buttons.find(b=>b.dataset.block===e.detail.blockId);if(b)this.select(Number(b.dataset.select));},options);
  }
  fitTitle(){const h=this.querySelector('.jg__heading');if(!h)return;h.style.fontSize='';if(matchMedia('(min-width:901px)').matches&&h.scrollWidth>h.clientWidth){h.style.fontSize=(parseFloat(getComputedStyle(h).fontSize)*h.clientWidth/h.scrollWidth*.99)+'px';}}
  select(index){if(!this.buttons[index])return;this.buttons.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));['scene','foreground','product'].forEach(key=>this.querySelectorAll('[data-'+key+']').forEach(el=>el.hidden=Number(el.dataset[key])!==index));}
  disconnectedCallback(){this.controller?.abort();this.resizeObserver?.disconnect();}
 });
}

{% endjavascript %}
{% schema %}
{
  "name": "June · Pick your pour",
  "tag": "section",
  "class": "june-pour-section",
  "max_blocks": 4,
  "settings": [
    {
      "type": "checkbox",
      "id": "use_master_palette",
      "label": "Use master palette",
      "default": true,
      "info": "Uses Theme settings > June master palette. Turn off to use this section’s individual colours."
    },
    {
      "type": "text",
      "id": "eyebrow",
      "label": "Eyebrow",
      "default": "Glassware"
    },
    {
      "type": "text",
      "id": "heading",
      "label": "Heading",
      "default": "PICK YOUR POUR."
    },
    {
      "type": "inline_richtext",
      "id": "body",
      "label": "Supporting copy",
      "default": "Make the everyday <strong>a little more special.</strong>"
    },
    {
      "type": "text",
      "id": "choose",
      "label": "Selector label",
      "default": "What are you pouring?"
    },
    {
      "type": "text",
      "id": "shop",
      "label": "Shop button",
      "default": "Shop this glass"
    },
    {
      "type": "text",
      "id": "view",
      "label": "Unavailable product button",
      "default": "View this glass"
    },
    {
      "type": "text",
      "id": "all",
      "label": "Collection link label",
      "default": "All glassware"
    },
    {
      "type": "collection",
      "id": "collection",
      "label": "Glassware collection"
    },
    {
      "type": "text",
      "id": "from",
      "label": "Price prefix",
      "default": "From"
    },
    {
      "type": "color",
      "id": "background",
      "label": "Background",
      "default": "#FFFFFF"
    },
    {
      "type": "color",
      "id": "ink",
      "label": "Text",
      "default": "#171717"
    },
    {
      "type": "color",
      "id": "accent",
      "label": "Accent",
      "default": "#F56A28"
    },
    {
      "type": "font_picker",
      "id": "fallback_font",
      "label": "Fallback font",
      "default": "poppins_n4"
    },
    {
      "type": "range",
      "id": "height",
      "label": "Minimum desktop height",
      "min": 400,
      "max": 700,
      "step": 10,
      "unit": "px",
      "default": 500,
      "info": "The photographic stage maintains a 1.92:1 ratio unless this minimum needs more room."
    },
    {
      "type": "range",
      "id": "mobile_height",
      "label": "Mobile photograph height",
      "min": 240,
      "max": 480,
      "step": 10,
      "unit": "px",
      "default": 340
    },
    {
      "type": "checkbox",
      "id": "motion",
      "label": "Enable button hover motion",
      "default": true
    },
    {
      "type": "range",
      "id": "speed",
      "label": "Hover speed",
      "min": 50,
      "max": 200,
      "step": 10,
      "unit": "%",
